#!/usr/bin/env python3
import json
import sys
import os

def trim_squad(in_file, out_file, n=10):
    with open(in_file, 'r') as f:
        data = json.load(f)
    count = 0
    out_articles = []
    for article in data["data"]:
        out_paragraphs = []
        for paragraph in article["paragraphs"]:
            new_qas = []
            for qa in paragraph["qas"]:
                if count < n:
                    new_qas.append(qa)
                    count += 1
                else:
                    break
            if new_qas:
                # Only add paragraphs that have at least one qas
                new_para = dict(paragraph)
                new_para["qas"] = new_qas
                out_paragraphs.append(new_para)
            if count >= n:
                break
        if out_paragraphs:
            new_article = dict(article)
            new_article["paragraphs"] = out_paragraphs
            out_articles.append(new_article)
        if count >= n:
            break
    trimmed = {"data": out_articles, "version": data.get("version", "1.1")}
    with open(out_file, 'w') as f:
        json.dump(trimmed, f)
    print(f"Wrote {min(count, n)} QAs to {out_file}")

def main():
    if len(sys.argv) < 3:
        print("Usage: trim_squad.py <in_file> <out_file> [n]")
        exit(1)
    in_file = sys.argv[1]
    out_file = sys.argv[2]
    n = int(sys.argv[3]) if len(sys.argv) > 3 else 10
    trim_squad(in_file, out_file, n)

if __name__ == "__main__":
    main()

