      5: {"id": "", "context": "All of Notre Dame's undergraduate students are a part of one of the five undergraduate colleges at the school or are in the First Year of Studies program. The First Year of Studies program was established in 1962 to guide incoming freshmen in their first year at the school before they have declared a major. Each student is given an academic advisor from the program who helps them to choose classes that give them exposure to any major in which they are interested. The program also includes a Learning Resource Center which provides time management, collaborative learning, and subject tutoring. This program has been recognized previously, by U.S. News & World Report, as outstanding.", "qas": [{"answers": ["Learning Resource Center"], "question": "What entity provides help with the management of time for new students at Notre Dame?", "id": "5733a70c4776f41900660f64", "qid": "ce2e16533d0c433e98323f77e50b7bee", "question_tokens": [["What", 0], ["entity", 5], ["provides", 12], ["help", 21], ["with", 26], ["the", 31], ["management", 35], ["of", 46], ["time", 49], ["for", 54], ["new", 58], ["students", 62], ["at", 71], ["Notre", 74], ["Dame", 80], ["?", 84]], "detected_answers": [{"text": "Learning Resource Center", "char_spans": [[496, 519]], "token_spans": [[92, 94]]}]}, {"answers": ["five"], "question": "How many colleges for undergraduates are at Notre Dame?", "id": "5733a70c4776f41900660f62", "qid": "f4d9caf76e9540ae87b455e0b322844d", "question_tokens": [["How", 0], ["many", 4], ["colleges", 9], ["for", 18], ["undergraduates", 22], ["are", 37], ["at", 41], ["Notre", 44], ["Dame", 50], ["?", 54]], "detected_answers": [{"text": "five", "char_spans": [[68, 71]], "token_spans": [[14, 14]]}]}, {"answers": ["The First Year of Studies program"], "question": "What was created at Notre Dame in 1962 to assist first year students?", "id": "5733a70c4776f41900660f63", "qid": "bf2e0f1a70fd46d683a8dc9d5d457f11", "question_tokens": [["What", 0], ["was", 